import React from 'react';
import { Link } from 'react-router-dom';


function Home() {
  return (
    <div className="home-page" style={{ padding: '0px', boxSizing: 'border-box', width: '100%' }}>
      {/* Promotional Banner with Image */}
      <div className="home-hero-banner" style={{
        width: '100%',
        background: 'linear-gradient(135deg, #ff9900 0%, #ff6600 100%)',
        borderRadius: '12px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        padding: '40px 50px',
        boxSizing: 'border-box',
        boxShadow: '0 6px 20px rgba(0, 0, 0, 0.1)',
        color: '#ffffff'
      }}>
        <div className="hero-banner-content" style={{ display: 'flex', flexDirection: 'column', gap: '15px', maxWidth: '500px' }}>
          <span style={{ 
            backgroundColor: '#ffffff', 
            color: '#cc6600', 
            fontSize: '13px', 
            fontWeight: '800', 
            textTransform: 'uppercase', 
            padding: '6px 14px', 
            borderRadius: '20px', 
            width: 'fit-content',
            letterSpacing: '1px' 
          }}>
            Sale is live
          </span>
          <h1 style={{ fontSize: '52px', fontWeight: '900', margin: 0, lineHeight: 1 }}>Starting ₹49</h1>
          <h2 style={{ fontSize: '24px', fontWeight: '700', margin: 0 }}>Home, kitchen, toys & outdoors</h2>
          <Link to="/products" style={{ 
            marginTop: '10px', 
            backgroundColor: '#130352', 
            color: '#ffffff', 
            padding: '12px 28px', 
            borderRadius: '6px', 
            fontWeight: '700', 
            textDecoration: 'none', 
            width: 'fit-content' 
          }}>
            Return to all deals &gt;
          </Link>
        </div>

        {/* Banner Image Box */}
        <div className="hero-banner-image" style={{ 
          width: '380px', 
          height: '250px', 
          borderRadius: '10px', 
          overflow: 'hidden', 
          boxShadow: '0 4px 15px rgba(0,0,0,0.15)' 
        }}>
          <img 
            src="https://images.unsplash.com/photo-1526170375885-4d8ecf77b99f?w=600" 
            alt="Promotion Banner" 
            style={{ width: '100%', height: '100%', objectFit: 'cover' }}
          />
        </div>
      </div>
    </div>
  );
}

export default Home;
